                    instrument: 'Murabaha',
                    rate: 5.0
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var instrumentSelect = document.getElementById('instrumentSelect');
            if (instrumentSelect) decisions.instrument = instrumentSelect.value;

            var rateInput = document.getElementById('rateInput');
            if (rateInput) decisions.rate = parseFloat(rateInput.value);

            if (!decisions.instrument) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('instrument_warning'), 'warning'
                );
                return false;
            }

            if (!decisions.rate || decisions.rate < 0.5 || decisions.rate > 50) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('rate_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var instrumentCorrect = (d.instrument === round.correctInstrument);
            var instrumentScore = instrumentCorrect ? 10 : 0;

            var rateDiff = Math.abs(d.rate - round.optimalRate);
            var rateRange = round.rateMax - round.rateMin;
            var rateAccuracy = Math.max(0, 1 - (rateDiff / (rateRange * 0.5)));
            var rateScore = Math.round(rateAccuracy * 6);

            if (d.rate < round.rateMin || d.rate > round.rateMax) {
                rateScore = 0;
            }

            var roundScore = instrumentScore + rateScore;

            var convTotal = round.dealValue * (round.conventionalRate / 100);
            var islamicTotal = round.dealValue * (d.rate / 100);

            state.domainState.totalScore += roundScore;
            state.domainState.roundsCompleted += 1;
            if (instrumentCorrect) {
                state.domainState.correctAnswers += 1;
            }
            state.domainState.scoreHistory.push(roundScore);
            state.domainState.cumulativeScoreHistory.push(state.domainState.totalScore);

            // Persist a normalized 0-100 score for the shared grading/reporting layer.
            var _maxScore = (state.maxPeriods || this.ROUNDS.length) * 16;
            var _overall = Math.min(100, Math.max(0, Math.round(100 * state.domainState.totalScore / Math.max(1, _maxScore))));
            var _tier = this._tierSlug(state.domainState.totalScore, state.domainState.correctAnswers);
            var _grade = this._letter(_overall);
            state.domainState.performance = { overallScore: _overall, score: _overall, grade: _grade, performanceTier: _tier };
            state.domainState.performanceTier = _tier;

            var n = idx + 1;
            var convDescL = this._t('s' + n + '_conv', round.conventionalDesc);
            var titleL = this._t('s' + n + '_title', round.title);

            var compPanel = document.getElementById('comparisonPanel');
            if (compPanel) compPanel.style.display = 'block';

            var convEl = document.getElementById('convCashFlow');
            if (convEl) {
                convEl.innerHTML = '<strong>' + convDescL.split('.')[0] + '</strong>' +
                    '<br>' + this._t('cf_annual_cost', 'Annual cost') + ': $' + convTotal.toLocaleString() +
                    '<br>' + this._t('cf_instrument', 'Instrument') + ': ' + this._t('conventional_col', 'Conventional') + ' ' + titleL.split(' ').pop();
            }

            var islamEl = document.getElementById('islamCashFlow');
            if (islamEl) {
                var statusIcon = instrumentCorrect ? '✅' : '❌';
                islamEl.innerHTML = '<strong>' + statusIcon + ' ' + d.instrument + '</strong>' +
                    '<br>' + this._t('cf_annual_cost', 'Annual cost') + ': $' + islamicTotal.toLocaleString() +
                    '<br>' + this._t('cf_rate_applied', 'Rate applied') + ': ' + d.rate + '%' +
                    '<br>' + this._t('cf_correct_instrument', 'Correct instrument') + ': ' + round.correctInstrument;
            }

            var fbEl = document.getElementById('feedbackText');
            if (fbEl) {
                fbEl.innerHTML = '<strong>' + window.mySimulation.t('score_earned') + ': ' + roundScore + '/16</strong>' +
                    '<br><br>' + this._t('s' + n + '_expl', round.explanation);
            }

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return {
                period: state.currentPeriod,
                scenarioTitle: round.title,
                instrument: d.instrument,
                correctInstrument: round.correctInstrument,
                instrumentCorrect: instrumentCorrect,
                rate: d.rate,
                optimalRate: round.optimalRate,
                roundScore: roundScore,
                totalScore: state.domainState.totalScore,
                overallScore: _overall,
                grade: _grade,
                performanceTier: _tier
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.totalScore',
                (v) => Math.round(v).toString());
            uiManager.bind('correctDisplay', 'domainState.correctAnswers',
                (v) => v.toString());
            uiManager.bind('roundScoreDisplay', 'results.roundScore',
                (v) => v !== undefined ? v + '/16' : '—');
        }

