        getChartData(state) {
            var labels = state.domainState.scoreHistory.map(function(_, i) {
                return 'S' + (i + 1);
            });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.scoreHistory },
                        { data: state.domainState.cumulativeScoreHistory }
                    ]
