        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.roundScore || 0 : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var correctPicks = history.filter(function(r) { return r.results && r.results.instrumentCorrect; }).length;
            var avgScore = totalScore / scores.length;

            var tierSlug = this._tierSlug(totalScore, correctPicks);
            var overall = Math.min(100, Math.max(0, Math.round(100 * totalScore / (this.ROUNDS.length * 16))));

            var insights = [];
            if (correctPicks === 6) {
                insights.push(this._t('ins_perfect', 'Perfect instrument selection — excellent knowledge of Sharia-compliant product mapping.'));
            } else if (correctPicks >= 4) {
                insights.push(this._t('ins_good', 'Good instrument knowledge. Review the scenarios you missed to strengthen product-structure matching.'));
            } else {
                insights.push(this._t('ins_focus', 'Focus on understanding which Sharia instruments map to each conventional financing need.'));
            }

            if (avgScore >= 13) {
                insights.push(this._t('ins_rate_strong', 'Strong rate-setting ability — you understand Islamic finance pricing well.'));
            } else {
                insights.push(this._t('ins_rate_practice', 'Practice calibrating financing rates relative to conventional benchmarks.'));
            }

            return {
                totalScore: totalScore,
                maxPossible: 96,
                overallScore: overall,
                correctPicks: correctPicks,
                avgRoundScore: Math.round(avgScore * 10) / 10,
                grade: this._letter(overall),
                performance: this._tierLabel(tierSlug),
                performanceTier: tierSlug,
                performanceLabel: this._tierLabel(tierSlug),
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (!results.instrumentCorrect) {
                return window.mySimulation.t('hint_wrong_instrument');
            }
            if (results.roundScore < 10) {
                return window.mySimulation.t('hint_adjust_rate');
            }
            if (results.roundScore >= 14) {
                return window.mySimulation.t('hint_excellent');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.scenarioTitle', label: 'Scenario', i18nKey: 'col_scenario' },
                { key: 'results.instrument', label: 'Your Pick', i18nKey: 'col_your_pick' },
                { key: 'results.correctInstrument', label: 'Correct', i18nKey: 'col_correct' },
                { key: 'results.instrumentCorrect', label: 'Match', i18nKey: 'col_match', formatter: function(v) { return v ? '✅' : '❌'; } },
                { key: 'results.rate', label: 'Your Rate', i18nKey: 'col_your_rate', formatter: function(v) { return v + '%'; } },
                { key: 'results.optimalRate', label: 'Optimal', i18nKey: 'col_optimal', formatter: function(v) { return v + '%'; } },
                { key: 'results.roundScore', label: 'Score', i18nKey: 'col_score', formatter: function(v) { return v + '/16'; } }
            ];
        }

        _t(key, fallback) {
            var val = key;
            if (window.mySimulation && typeof window.mySimulation.t === 'function') { val = window.mySimulation.t(key); }
            if (val === key || val === undefined || val === null) { return (fallback !== undefined) ? fallback : key; }
            return val;
        }

        _letter(pct) {
            if (pct >= 90) return 'A';
            if (pct >= 75) return 'B';
            if (pct >= 60) return 'C';
            if (pct >= 40) return 'D';
            return 'F';
        }

        _tierSlug(totalScore, correctPicks) {
            if (totalScore >= 90 && correctPicks >= 6) return 'master';
            if (totalScore >= 80 && correctPicks >= 5) return 'expert';
            if (totalScore >= 60 && correctPicks >= 4) return 'proficient';
            return 'novice';
        }

        _tierLabel(slug) {
            var en = { novice: 'Novice', proficient: 'Proficient', expert: 'Expert', master: 'Master' };
            return this._t('tier_' + slug, en[slug] || 'Novice');
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore
                : (typeof summary.totalScore === 'number') ? Math.round(100 * summary.totalScore / (summary.maxPossible || 96)) : 0;
            var grade = summary.grade || this._letter(score);
            var tier = summary.performanceTier || 'novice';
            var label = summary.performanceLabel || this._tierLabel(tier);
            var correct = (typeof summary.correctPicks === 'number') ? summary.correctPicks : 0;
            var avg = (typeof summary.avgRoundScore === 'number') ? summary.avgRoundScore : 0;
            var insights = Array.isArray(summary.insights) ? summary.insights : [];
            var html = '' +
                '<div class="sharia-cm">' +
                '<div class="sharia-cm-title">' + this._t('cm_title', 'Exploration Complete') + '</div>' +
                '<div class="sharia-cm-score">' + score + '<span class="sharia-cm-score-max"> / 100</span></div>' +
                '<div class="sharia-cm-grade sharia-cm-grade-' + grade + '">' +
                    this._t('cm_grade', 'Grade') + ': <b>' + grade + '</b> &middot; ' + label + '</div>' +
                '<div class="sharia-cm-stats">' +
                    '<div class="sharia-cm-stat"><span>' + this._t('cm_correct', 'Correct Picks') + '</span><b>' + correct + ' / ' + this.ROUNDS.length + '</b></div>' +
                    '<div class="sharia-cm-stat"><span>' + this._t('cm_avg', 'Avg / Scenario') + '</span><b>' + avg + ' / 16</b></div>' +
                '</div>';
            if (insights.length) {
                html += '<div class="sharia-cm-insights"><div class="sharia-cm-insights-h">' + this._t('cm_insights', 'Insights') + '</div><ul>';
                for (var i = 0; i < insights.length; i++) { html += '<li>' + insights[i] + '</li>'; }
                html += '</ul></div>';
            }
            html += '</div>';
            return html;
        }

