        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var n = idx + 1;

            var isDone = (state.currentPeriod || 1) > this.ROUNDS.length;
            var controls = document.getElementById('shariaControls');
            if (isDone) { if (controls) controls.style.display = 'none'; return; }
            if (controls) controls.style.display = '';

            var titleEl = document.getElementById('scenarioTitle');
            if (titleEl) titleEl.innerHTML = this._t('s' + n + '_title', round.title);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = this._t('s' + n + '_desc', round.description);

            var convEl = document.getElementById('conventionalDesc');
            if (convEl) convEl.innerHTML = this._t('s' + n + '_conv', round.conventionalDesc);

            var dealEl = document.getElementById('dealValueDisplay');
            if (dealEl) dealEl.innerHTML = '$' + round.dealValue.toLocaleString();

            var rateInput = document.getElementById('rateInput');
            if (rateInput) { rateInput.min = round.rateMin; rateInput.max = round.rateMax; }

            // NOTE: intentionally NOT hiding #comparisonPanel here. Previously the
            // 500ms briefing-advance hid the cash-flow comparison + Sharia explanation
            // (both live inside #comparisonPanel) so the learner saw the core teaching
            // content for only half a second. It now persists until the next submission.
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new ShariaFinanceAdapter(), {
            simulationType: 'sharia_finance_235',
            maxPeriods: 6,
            autoSaveInterval: 30000
        });
    });

